import contextlib
import io
import json
import os
import sys

MOLAR_MASS = {"NaOH": 40.0, "HCl": 36.46, "KCl": 74.55}


def harness_fail(msg):
    print(json.dumps({"results": [], "harness_error": msg}))
    sys.exit(0)


def load_candidate():
    path = os.path.join(os.getcwd(), "block-0.txt")
    with open(path, "r", encoding="utf-8") as f:
        src = f.read()
    ns = {"__name__": "candidate_module"}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(src, "block-0.txt", "exec"), ns)
    return ns["Solute"], ns["Solution"]


def run_ops(ops, Solute, Solution):
    solutes = {}
    pool = []
    last = None
    for op in ops:
        kind = op["op"]
        if kind == "prepare":
            name = op["solute"]
            if name not in solutes:
                solutes[name] = Solute(name, MOLAR_MASS[name])
            vol = float(op["volume_mL"])
            moles = float(op["molarity"]) * vol / 1000.0
            last = Solution(solutes[name], moles, vol)
            pool.append(last)
        elif kind == "mix":
            items = list(op["items"])
            acc = None
            for i in items:
                sol = pool[i]
                acc = sol if acc is None else acc.mix(sol)
            for i in items:
                pool[i] = None
            last = acc
            pool.append(acc)
        elif kind == "take":
            idx = op["source"]
            taken, remaining = pool[idx].take_volume(float(op["volume_mL"]))
            pool[idx] = remaining
            last = taken
            pool.append(taken)
        else:
            raise ValueError("unknown op: " + str(kind))
    if last is None:
        raise ValueError("no solution produced")
    return {
        "solute": last.solute.name,
        "volume_mL": last.volume_ml,
        "moles": last.moles,
        "molarity": last.molarity_M,
    }


def main():
    try:
        with open(os.path.join(os.getcwd(), "inputs.json"), "r", encoding="utf-8") as f:
            cases = json.load(f)
    except Exception as e:
        harness_fail("cannot read inputs.json: " + repr(e))
    try:
        Solute, Solution = load_candidate()
    except Exception as e:
        harness_fail("cannot load candidate: " + repr(e))
    results = []
    for case in cases:
        cid = case.get("id")
        try:
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                out = run_ops(case["input"]["ops"], Solute, Solution)
            results.append({"id": cid, "actual": out})
        except Exception as e:
            results.append({"id": cid, "error": type(e).__name__ + ": " + str(e)})
    print(json.dumps({"results": results}))


if __name__ == "__main__":
    main()
